    )

def cleanup_recalculate_all_guild_levels():
    init_guild_system()
    cursor.execute("SELECT id FROM guilds")
    rows = cursor.fetchall()
    updated = 0

    for row in rows:
        try:
            guild_id = row["id"]
        except Exception:
            guild_id = row[0]
        old = get_guild_by_id(guild_id)["level"]
        new = recalculate_guild_level(guild_id)
        if new != old:
            updated += 1

    return updated

